  { id: "caatinga", fotos: [{ src: "img/29-mapa-caatinga-paisagem.jpg", legenda: "A Caatinga vista do espaço (área destacada)" }], regiao: "Caatinga (Brasil)", nome: "Neoglaziovia variegata", apelido: "Caroá", cor: "#EA580C", texto_cor: "#C2410C", soft: "#FFEDD5", photoBg: "linear-gradient(160deg,#FFEDD5,#FEF9C3)", foto: "caroá no chão pedregoso do sertão", superpoder: "tolerância à seca", habitat: "Chão seco e pedregoso do sertão nordestino", texto: "Adaptado ao semiárido, o caroá realiza metabolismo CAM: abre os estômatos à noite, quando a temperatura é menor, e reduz a perda de água. Suas folhas fornecem fibras resistentes, usadas tradicionalmente no Nordeste em tecelagem, cordoaria e artesanato.", ficha: [{ k: "Fotossíntese", v: "CAM (noturna)" }, { k: "Uso humano", v: "Fibras e artesanato" }] },
  { id: "mata", fotos: [{ src: "img/30-mapa-mata-atlantica-alcantarea.jpg", legenda: "Bromélias-imperiais (Alcantarea imperialis)" }, { src: "img/31-mapa-mata-atlantica-perereca.jpg", legenda: "Perereca-de-bromélia (Phyllodytes maculosus)" }], regiao: "Mata Atlântica (Brasil)", nome: "Alcantarea imperialis", apelido: "Bromélia-imperial", cor: "#DB2777", texto_cor: "#BE185D", soft: "#FCE7F3", photoBg: "linear-gradient(160deg,#FCE7F3,#D1FAE5)", foto: "bromélia-imperial num paredão de granito", superpoder: "vida sobre a rocha", habitat: "Paredões de granito das serras do Rio de Janeiro", texto: "É uma espécie rupícola: cresce sobre paredões de granito quase verticais, onde poucas plantas conseguem se fixar. Seu tanque acumula litros de água e abriga uma comunidade de anfíbios e invertebrados. Pelo valor ornamental, sofreu com a extração ilegal; por isso, só devem ser comercializadas mudas de viveiros legalizados.", ficha: [{ k: "Roseta", v: "Mais de 1 m de largura" }, { k: "Mora em", v: "Rochas (rupícola)" }] },
  { id: "africa", fotos: [{ src: "img/32-mapa-africa-futa-jalom.jpg", legenda: "Rochedos do Futa Jalom, na Guiné: o lar da Pitcairnia feliciana" }, { src: "img/33-mapa-africa-pitcairnia-parente.jpg", legenda: "Uma prima americana do gênero Pitcairnia" }], regiao: "África Ocidental (Guiné)", nome: "Pitcairnia feliciana", apelido: "A exceção africana", cor: "#DB2777", texto_cor: "#BE185D", soft: "#FCE7F3", photoBg: "linear-gradient(160deg,#FCE7F3,#FFEDD5)", foto: "Pitcairnia feliciana nos rochedos de Futa Jalom", superpoder: "dispersão transatlântica", habitat: "Rochedos de arenito nas montanhas de Futa Jalom, na Guiné", texto: "É a única bromélia nativa fora das Américas. Estudos moleculares indicam que se separou das espécies americanas há cerca de 10 milhões de anos, muito depois da separação entre África e América do Sul. Por isso, a hipótese mais aceita é a de dispersão a longa distância: sementes teriam cruzado o Atlântico, possivelmente levadas por aves migratórias. Coletada pela primeira vez em 1937, hoje está classificada como Em perigo (IUCN).", ficha: [{ k: "Descoberta", v: "1937" }, { k: "Status", v: "Em perigo (IUCN)" }], especial: true }
