const PARTES = [{"n": 1, "t": "Bráctea floral", "d": "Pequena folha modificada que envolve e protege cada flor. Em muitas espécies é colorida e dura bem mais do que a própria flor, mantendo a inflorescência vistosa por semanas.", "left": "76.32%", "top": "2.89%", "tr": "translate(0, -50%)"}, {"n": 2, "t": "Bráctea primária", "d": "Bráctea maior, situada na base de cada espiga. Delimita os ramos da inflorescência e muitas vezes tem cor diferente das brácteas florais.", "left": "23.68%", "top": "7.89%", "tr": "translate(-100%, -50%)"}, {"n": 3, "t": "Espiga", "d": "Ramo da inflorescência em que as flores se prendem diretamente ao eixo, sem pedicelo. Em gêneros como Tillandsia e Vriesea costuma ser achatada, com as brácteas em duas fileiras opostas (disposição dística).", "left": "76.32%", "top": "13.16%", "tr": "translate(0, -50%)"}, {"n": 4, "t": "Inflorescência", "d": "Conjunto de flores e brácteas no alto do pedúnculo. Pode ser simples, com uma única espiga, ou composta, com várias espigas, como nesta ilustração.", "left": "23.68%", "top": "17.76%", "tr": "translate(-100%, -50%)"}, {"n": 5, "t": "Flores", "d": "Trímeras: 3 sépalas, 3 pétalas e 6 estames. Ficam abertas por pouco tempo; aqui aparecem como as pétalas tubulares amarelas que saem de entre as brácteas.", "left": "76.32%", "top": "27.63%", "tr": "translate(0, -50%)"}, {"n": 6, "t": "Pedúnculo (escapo)", "d": "Haste que eleva a inflorescência acima da roseta. Deixa as flores mais expostas aos polinizadores e as sementes mais expostas ao vento.", "left": "76.32%", "top": "39.47%", "tr": "translate(0, -50%)"}, {"n": 7, "t": "Bráctea do pedúnculo", "d": "Folhas reduzidas que envolvem o pedúnculo. Protegem a haste durante o crescimento e marcam a transição entre as folhas comuns e as brácteas da inflorescência.", "left": "23.68%", "top": "57.89%", "tr": "translate(-100%, -50%)"}, {"n": 8, "t": "Lâmina foliar", "d": "Parte alongada da folha, onde ocorre a maior parte da fotossíntese. A margem pode ser lisa ou espinhosa, e a superfície costuma ser coberta de tricomas.", "left": "23.68%", "top": "71.05%", "tr": "translate(-100%, -50%)"}, {"n": 9, "t": "Roseta", "d": "Arranjo das folhas em espiral, todas partindo de um caule muito curto. Nas bromélias-tanque, as bases sobrepostas das folhas acumulam água e matéria orgânica.", "left": "23.68%", "top": "80.53%", "tr": "translate(-100%, -50%)"}, {"n": 10, "t": "Bainha foliar", "d": "Base alargada da folha, mais clara que a lâmina, que abraça o caule e as folhas vizinhas. É a sobreposição das bainhas que forma o tanque.", "left": "76.32%", "top": "85.53%", "tr": "translate(0, -50%)"}, {"n": 11, "t": "Rebentos", "d": "Brotos laterais que nascem na base da planta-mãe. São clones dela e garantem a reprodução assexuada, principalmente depois da floração.", "left": "23.68%", "top": "91.84%", "tr": "translate(-100%, -50%)"}, {"n": 12, "t": "Raízes", "d": "Fixam a planta ao solo, à rocha ou ao galho. Nas terrestres absorvem água e sais minerais; nas epífitas a função principal é a fixação.", "left": "76.32%", "top": "97.11%", "tr": "translate(0, -50%)"}];
const ETAPAS = [{"n": 1, "t": "Semente", "d": "Formada no fruto depois da fecundação dos óvulos. Nas cápsulas, as sementes têm plumas (Tillandsioideae) ou asas (Pitcairnioideae) e são levadas pelo vento; nas bagas, são levadas por animais. Só uma fração muito pequena encontra um lugar adequado para germinar.", "tag": "Sexuada", "fato": "Cada fruto pode produzir centenas de sementes, mas só uma pequena fração chega a um lugar com luz, umidade e apoio para germinar."}, {"n": 2, "t": "Plântula", "d": "Com umidade, luz e temperatura adequadas, a semente germina sobre um galho, uma rocha ou o solo. As primeiras folhas são pequenas e as raízes logo prendem a plântula ao suporte.", "tag": "Sexuada", "fato": "Plântulas epífitas costumam germinar em fendas de cascas e em tufos de musgo, que seguram umidade como uma esponja."}, {"n": 3, "t": "Juvenil", "d": "A planta cresce devagar, acrescentando folhas à roseta. Em muitas espécies-tanque, os jovens ainda dependem mais dos tricomas do que de um tanque, que só se forma quando a roseta fica grande.", "tag": "Crescimento", "fato": "Nas bromélias-tanque, o copo central só se forma quando a roseta já tem várias folhas sobrepostas."}, {"n": 4, "t": "Adulta", "d": "Depois de 2 a 30 anos, conforme a espécie, a roseta atinge o tamanho máximo e acumula reservas para florescer. Na Puya raimondii essa espera pode passar de 40 anos.", "tag": "Maturidade", "fato": "A Puya raimondii pode esperar mais de 40 anos para florescer; muitas bromélias de jardim levam de 2 a 5."}, {"n": 5, "t": "Floração", "d": "O pedúnculo se alonga e a inflorescência se abre. A maioria das bromélias é monocárpica, ou seja, floresce uma única vez. Algumas, como certas Tillandsia, lançam várias inflorescências ao longo da vida.", "tag": "Reprodução", "fato": "As brácteas coloridas podem durar semanas, muito mais do que cada flor, que muitas vezes abre por um único dia."}, {"n": 6, "t": "Frutos e dispersão", "d": "Após a polinização, formam-se cápsulas ou bagas com muitas sementes. Elas são liberadas e dispersas, fechando o ciclo sexual.", "tag": "Dispersão", "fato": "Sementes com plumas viajam com o vento como paraquedas; sementes de bagas passam pelo intestino de aves e morcegos e germinam longe da mãe."}, {"n": 7, "t": "Rebentos", "d": "Durante ou depois da floração surgem brotos laterais na base. A planta-mãe envelhece e morre, enquanto os rebentos, clones dela, crescem até a fase adulta: é o ciclo assexuado.", "tag": "Assexuada", "fato": "Viveiros produzem mudas separando rebentos: é a forma legal de multiplicar bromélias sem retirar plantas da natureza."}];
