const REGIOES = [{"id": "litoral", "nome": "Mata Atlântica", "cor": "#059669", "num": "266 táxons", "pct": "61%", "d": "A maior parte das bromélias da Bahia vive na faixa úmida do litoral, em florestas, restingas e afloramentos. Gêneros como Hohenbergia, Aechmea, Wittmackia e Lymania têm muitas espécies que só existem no estado.", "ex": "Hohenbergia, Aechmea, Wittmackia, Lymania"}, {"id": "caatinga", "nome": "Caatinga", "cor": "#C2410C", "num": "86 táxons", "pct": "20%", "d": "No semiárido, as bromélias são terrestres ou crescem em rochas, com folhas duras e espinhosas e metabolismo CAM. A macambira e o caroá são usados por comunidades do sertão, e espécies de Encholirium dominam lajedos rochosos.", "ex": "macambira, caroá, Encholirium, Tillandsia"}, {"id": "chapada", "nome": "Chapada Diamantina", "cor": "#7C3AED", "num": "campos rupestres", "pct": "endemismos", "d": "Nos campos rupestres das serras, muitas espécies vivem só em alguns morros. É lá que ocorre Cottendorfia florida, a única Navioideae da Bahia, endêmica do estado.", "ex": "Orthophytum, Vriesea, Cottendorfia"}, {"id": "cerrado", "nome": "Cerrado", "cor": "#CA8A04", "num": "14 espécies", "pct": "3%", "d": "No oeste baiano, o Cerrado tem poucas bromélias, geralmente terrestres e adaptadas ao fogo e à seca, como espécies de Dyckia e abacaxis silvestres.", "ex": "Dyckia, Ananas"}];
const CHAVE = {"q1": {"q": "Observe a margem das folhas. Tem espinhos ou serrilhas?", "help": "Olhe a borda da folha de perto na foto. Na planta real, passe o dedo com cuidado.", "ops": [["Sim, tem espinhos ou serrilhas", "q2"], ["Não, a margem é lisa", "q3"]]}, "q2": {"q": "Há fruto ou flor? O que mais chama atenção?", "help": "Frutos carnosos e suculentos são bagas; o abacaxi é um fruto múltiplo carnoso.", "ops": [["Fruto carnoso (baga) ou infrutescência", "R_brom"], ["Sem flores; as folhas formam um tanque com água", "R_brom_prov"], ["Sem tanque; planta de solo seco ou rocha, folhas duras", "R_pitc"]]}, "q3": {"q": "Como a planta vive?", "help": "Epífitas crescem sobre outras plantas; as atmosféricas ficam penduradas ou soltas e são prateadas.", "ops": [["Pendurada ou presa a galhos, prateada, sem tanque", "R_till"], ["Forma tanque e tem folhas lisas e brilhantes", "R_till_tanque"]]}};
const CHAVE_RES = {"R_brom": {"nome": "Bromelioideae", "cor": "#BE185D", "d": "Fruto carnoso indica ovário ínfero e baga, a marca de Bromelioideae, a subfamília do abacaxi."}, "R_brom_prov": {"nome": "Provavelmente Bromelioideae", "cor": "#BE185D", "d": "Espinhos na margem e tanque bem formado são comuns em Bromelioideae. Para ter certeza, observe a flor: o ovário deve ser ínfero e o fruto, uma baga."}, "R_pitc": {"nome": "Provavelmente Pitcairnioideae (sentido amplo)", "cor": "#C2410C", "d": "Folhas duras e espinhosas, sem tanque, em solo seco ou rocha lembram Dyckia, Encholirium e Puya. Na classificação atual elas podem estar em Pitcairnioideae ou em Puyoideae."}, "R_till": {"nome": "Tillandsioideae (atmosférica)", "cor": "#1F66A8", "d": "Margem lisa, sem tanque e coberta de tricomas prateados: é o perfil das Tillandsia atmosféricas."}, "R_till_tanque": {"nome": "Provavelmente Tillandsioideae", "cor": "#1F66A8", "d": "Tanque com folhas lisas, sem espinhos, é típico de Vriesea e Guzmania. Confirme pelas sementes plumosas dentro de um fruto em cápsula."}};
const EXEMPLARES = [{"id": "livre", "nome": "Modo livre (qualquer bromélia)", "img": "img/uefs-u10.jpg", "credito": "", "exp": null, "explica": ""}, {"id": "amarela", "nome": "Bromélia amarela da UEFS", "img": "img/uefs-u2.jpg", "credito": "Foto autoral · UEFS", "exp": "R_brom_prov", "explica": "Ela tem espinhos na margem e tanque com água, mas não estava florida. Por isso o resultado mais honesto é “provavelmente Bromelioideae”."}, {"id": "abacaxi", "nome": "Abacaxi ornamental da UEFS", "img": "img/uefs-u8.jpg", "credito": "Foto autoral · UEFS", "exp": "R_brom", "explica": "Folhas serrilhadas e fruto múltiplo carnoso: o abacaxi é uma Bromelioideae."}, {"id": "barba", "nome": "Barba-de-velho", "img": "img/21-mapa-eua-barba-de-velho.jpg", "credito": "Foto: Wikimedia Commons", "exp": "R_till", "explica": "Sem espinhos, sem tanque e prateada: Tillandsia usneoides, uma Tillandsioideae atmosférica."}];
