const FALSAS = [{"nome": "Agave (piteira)", "cient": "Agave sp.", "aparencia": "Roseta enorme de folhas grossas, suculentas e com um espinho forte na ponta. Vive em lugares secos.", "resp": false, "explica": "Não é bromélia: agave é da família Asparagaceae. As folhas são suculentas e fibrosas, sem tricomas peltados, e as flores têm 6 tépalas iguais."}, {"nome": "Abacaxi", "cient": "Ananas comosus", "aparencia": "Roseta de folhas duras e serrilhadas, com um fruto carnoso no alto de uma haste.", "resp": true, "explica": "É bromélia! O abacaxi é da subfamília Bromelioideae, com fruto múltiplo carnoso."}, {"nome": "Babosa", "cient": "Aloe vera", "aparencia": "Roseta de folhas grossas e carnudas, cheias de gel, com dentinhos na margem.", "resp": false, "explica": "Não é bromélia: babosa é da família Asphodelaceae. O gel é tecido de reserva de água, e as flores são tubulares com 6 tépalas."}, {"nome": "Barba-de-velho", "cient": "Tillandsia usneoides", "aparencia": "Fios prateados pendurados nas árvores, parecidos com musgo ou líquen. Não tem raízes quando adulta.", "resp": true, "explica": "É bromélia! Uma Tillandsioideae atmosférica, coberta de tricomas, mesmo sem parecer com uma."}, {"nome": "Planta-aranha", "cient": "Chlorophytum comosum", "aparencia": "Tufo de folhas finas e moles, verdes com faixas brancas, que solta filhotes pendurados em hastes.", "resp": false, "explica": "Não é bromélia: é da família Asparagaceae. As folhas não têm tricomas peltados e os filhotes nascem em estolões, não na base da roseta."}, {"nome": "Guzmânia", "cient": "Guzmania lingulata", "aparencia": "Roseta de folhas lisas e brilhantes com um centro vermelho vivo, vendida em floriculturas.", "resp": true, "explica": "É bromélia! Uma Tillandsioideae de tanque: o “centro vermelho” são brácteas, e as flores verdadeiras são pequenas."}, {"nome": "Cordiline", "cient": "Cordyline fruticosa", "aparencia": "Folhas largas e avermelhadas no alto de um caule fino e alto, muito usada em jardins.", "resp": false, "explica": "Não é bromélia: é da família Asparagaceae. Tem caule alongado e folhas com pecíolo; não forma roseta com tanque."}, {"nome": "Pândano", "cient": "Pandanus sp.", "aparencia": "Arbusto ou árvore com folhas longas e serrilhadas em espiral e raízes aéreas que sustentam o tronco.", "resp": false, "explica": "Não é bromélia: é da família Pandanaceae. As folhas saem em três fileiras espiraladas de um tronco ramificado, com raízes-escora."}];
